*{box-sizing:border-box}
:root{
  --text:#fff7ed;--muted:#d7deea;--sand:#f4c27a;--red:#d56a47;
  font-family:Inter,system-ui,-apple-system,"Segoe UI",sans-serif;color-scheme:dark
}
html{min-height:100%;background:#111}
body{
  margin:0;min-height:100vh;min-height:100dvh;color:var(--text);
  background-image:
    linear-gradient(180deg,rgba(5,9,18,.05),rgba(5,9,18,.12) 45%,rgba(5,9,18,.45)),
    url('data:image/png;base64,');
  background-position:center center;
  background-size:cover;
  background-repeat:no-repeat;
  background-attachment:fixed;
}
button,input,textarea{font:inherit}
button{cursor:pointer}
.app{width:min(760px,100%);margin:auto;min-height:100dvh;padding-bottom:94px}
header{display:flex;justify-content:space-between;align-items:center;padding:calc(12px + env(safe-area-inset-top)) 18px 10px}
header h1{font-size:1.28rem;margin:2px 0 0;text-shadow:0 2px 18px rgba(0,0,0,.55)}
.eyebrow{font-size:.68rem;letter-spacing:.16em;font-weight:900;color:#ffd18b;text-shadow:0 2px 12px #000}
.australia{font-size:.65rem;letter-spacing:.17em;font-weight:900;border:1px solid rgba(255,209,139,.55);border-radius:999px;padding:7px 10px;color:#ffe0ad;background:rgba(5,9,18,.42);backdrop-filter:blur(8px)}
main{padding:0 16px 14px}
.page{display:none}.page.active{display:block}
.hero{min-height:265px;display:flex;flex-direction:column;justify-content:flex-end;padding:20px;border:1px solid rgba(255,255,255,.20);border-radius:28px;background:linear-gradient(180deg,rgba(5,9,18,.03),rgba(5,9,18,.28));backdrop-filter:blur(2px);box-shadow:0 20px 54px rgba(0,0,0,.18)}
.chip{align-self:flex-start;font-size:.66rem;font-weight:800;letter-spacing:.08em;color:#ffe0ad;background:rgba(115,53,35,.50);border:1px solid rgba(255,214,161,.30);padding:7px 10px;border-radius:999px}
.hero h2{font-size:clamp(2.8rem,11.5vw,4.7rem);line-height:.88;letter-spacing:-.06em;margin:14px 0 10px;text-shadow:0 4px 24px rgba(0,0,0,.55)}
.hero h2 em{font-style:normal;color:#f6bf76}
.hero p{margin:0;color:#fff;text-shadow:0 2px 10px rgba(0,0,0,.6)}
.cards{display:grid;gap:12px;margin-top:12px}
.cards button{display:grid;grid-template-columns:48px 1fr auto;align-items:center;gap:12px;text-align:left;color:var(--text);border:1px solid rgba(255,255,255,.18);background:rgba(8,14,28,.44);border-radius:22px;padding:16px;backdrop-filter:blur(12px);box-shadow:0 10px 24px rgba(0,0,0,.10)}
.cards button>span{display:grid;place-items:center;width:46px;height:46px;border-radius:14px;background:rgba(213,106,71,.18)}
.cards strong{display:block;font-size:1.03rem}.cards small{display:none}.cards b{font-size:1.5rem;color:#cbd5e1}
.notice,.personal-banner{display:grid;grid-template-columns:auto 1fr;gap:11px;border-radius:22px;padding:14px 16px;margin-top:10px;backdrop-filter:blur(10px)}
.notice.personal,.personal-banner{border:1px solid rgba(87,223,208,.32);background:rgba(7,47,44,.48)}
.notice.shared{border:1px solid rgba(244,194,122,.30);background:rgba(75,38,21,.46)}
.notice p,.personal-banner small{display:block;margin:4px 0 0;color:#e4fbf7;font-size:.82rem;line-height:1.4}.notice.shared p{color:#ffe0c8}.notice.compact p{display:none}.notice.compact strong{display:block;padding:2px 0}
.sync-status{margin-top:10px;padding:12px 14px;border-radius:18px;font-size:.88rem;background:rgba(8,14,28,.42);border:1px solid rgba(255,255,255,.14);color:#e6edf8;backdrop-filter:blur(10px)}
.title-row{display:flex;justify-content:space-between;align-items:end;margin:12px 2px 16px}.title-row h2{font-size:2rem;margin:4px 0 0;text-shadow:0 2px 12px #000}
.ghost{border:1px solid rgba(255,255,255,.18);border-radius:11px;background:rgba(0,0,0,.32);color:#edf2fb;padding:9px 12px}
.add-form,.time-form,.form-card,.progress{border:1px solid rgba(255,255,255,.18);background:rgba(8,14,28,.58);backdrop-filter:blur(12px);border-radius:20px;padding:13px;margin-top:10px}
.add-form{display:grid;grid-template-columns:1fr 50px;gap:8px}
input,textarea{width:100%;border:1px solid rgba(255,255,255,.16);background:rgba(4,8,17,.52);color:white;padding:13px 14px;border-radius:12px;outline:none}
input:focus,textarea:focus{border-color:#e19c61;box-shadow:0 0 0 3px rgba(225,156,97,.12)}
.add-form button,.time-form button,.save-btn{border:0;border-radius:12px;background:linear-gradient(135deg,#e07d56,#c04a37);color:white;font-weight:900}
.add-form button{font-size:1.25rem}
.progress>div{display:flex;justify-content:space-between;font-size:.85rem}.progress i{display:block;height:8px;margin-top:10px;border-radius:999px;background:#08101d;overflow:hidden}.progress u{display:block;height:100%;width:0;background:linear-gradient(90deg,#e28155,#f4c27a);border-radius:inherit;text-decoration:none}
.list{display:grid;gap:9px;margin-top:10px}
.pack,.event{display:grid;gap:10px;align-items:center;border:1px solid rgba(255,255,255,.18);background:rgba(8,14,28,.58);border-radius:16px;padding:12px 13px;backdrop-filter:blur(10px)}
.pack{grid-template-columns:auto 1fr auto}.pack input{width:20px;height:20px;accent-color:#d56a47}.pack.done .label{text-decoration:line-through;color:#a6b0bf}
.del{border:0;background:transparent;color:#d6deeb;font-size:1rem}
.time-form{display:grid;grid-template-columns:1fr 120px;gap:8px}.time-form #timeAct,.time-form #timeName,.time-form button{grid-column:1/-1}.time-form button{padding:13px}
.event{grid-template-columns:68px 1fr auto}.event .time{font-weight:900;color:#ffd08a}.event small{display:block;color:#e0e6ef;margin-top:3px}.event .meta{color:#c1cad8;font-size:.75rem;margin-top:4px}
.form-card label{display:block;margin-bottom:15px}.form-card label>span{display:block;font-size:.82rem;font-weight:800;margin:0 0 7px 2px}.form-card p{font-size:.8rem;color:#d1d8e5;margin:10px 0 0}
.save-btn{width:100%;padding:13px;margin-top:3px}
nav{position:fixed;left:50%;bottom:8px;transform:translateX(-50%);width:min(720px,calc(100% - 20px));display:grid;grid-template-columns:repeat(4,1fr);padding:10px 10px calc(10px + env(safe-area-inset-bottom));background:linear-gradient(180deg, rgba(6,10,19,.22), rgba(6,10,19,.14));backdrop-filter:blur(14px);-webkit-backdrop-filter:blur(14px);border:1px solid rgba(255,255,255,.10);border-radius:22px;box-shadow:0 12px 30px rgba(0,0,0,.15)}
nav button{border:0;background:transparent;color:#bec8d7;display:grid;justify-items:center;gap:3px;padding:4px 0}nav button span{font-size:1.1rem}nav small{font-size:.68rem}nav button.active{color:#ffd08a}
@media(max-width:700px){
  body{background-attachment:scroll;background-position:52% center}
}
@media(min-width:640px){
  .cards{grid-template-columns:repeat(3,1fr)}.cards button{grid-template-columns:1fr;min-height:150px;align-content:space-between}.cards b{display:none}
  .time-form{grid-template-columns:1fr 130px 2fr 1.2fr auto}.time-form #timeAct,.time-form #timeName,.time-form button{grid-column:auto}
}

nav button{ text-shadow:0 1px 6px rgba(0,0,0,.25); }

.app{padding-bottom:92px}

nav button span{font-size:1.18rem;line-height:1}
nav button.active span{transform:translateY(-1px)}

/* v18 additions */
body.locked{overflow:hidden}
.login-gate{
  position:fixed;inset:0;z-index:9999;display:grid;place-items:center;padding:20px;
  background:rgba(4,8,16,.72);backdrop-filter:blur(18px);-webkit-backdrop-filter:blur(18px)
}
.login-gate.hidden{display:none}
.login-card{
  width:min(380px,100%);border:1px solid rgba(255,255,255,.16);border-radius:26px;
  background:rgba(8,14,28,.72);backdrop-filter:blur(18px);padding:24px;box-shadow:0 24px 70px rgba(0,0,0,.32)
}
.login-card h2{font-size:2rem;margin:7px 0 8px}
.login-card p{color:#d7deea;margin:0 0 16px}
.login-card form{display:grid;gap:10px}
.login-card button{border:0;border-radius:13px;padding:13px;background:linear-gradient(135deg,#e07d56,#c04a37);color:#fff;font-weight:900}
#loginError{display:block;min-height:1.2em;margin-top:8px;color:#ffb4a7}

.countdown{
  display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin-top:16px
}
.countdown>div{
  text-align:center;padding:10px 6px;border:1px solid rgba(255,255,255,.13);border-radius:14px;
  background:rgba(5,9,18,.24);backdrop-filter:blur(8px)
}
.countdown b{display:block;font-size:1.25rem;color:#ffd08a}
.countdown span{display:block;font-size:.66rem;color:#dbe4f1;margin-top:2px}

.chat-form{
  display:grid;grid-template-columns:140px 1fr auto;gap:8px;
  border:1px solid rgba(255,255,255,.18);background:rgba(8,14,28,.48);
  backdrop-filter:blur(12px);border-radius:20px;padding:13px
}
.chat-form button{border:0;border-radius:12px;background:linear-gradient(135deg,#e07d56,#c04a37);color:#fff;font-weight:900;padding:0 16px}
.chat-list{display:grid;gap:9px;margin-top:10px}
.chat-msg{
  border:1px solid rgba(255,255,255,.16);background:rgba(8,14,28,.50);
  border-radius:18px;padding:12px 14px;backdrop-filter:blur(10px)
}
.chat-msg header{display:flex;justify-content:space-between;padding:0;margin:0 0 5px}
.chat-msg strong{font-size:.9rem}.chat-msg time{font-size:.72rem;color:#b8c3d2}
.chat-msg p{margin:0;color:#eef3fb;line-height:1.45;white-space:pre-wrap;word-break:break-word}

.map-card{
  border:1px solid rgba(255,255,255,.18);background:rgba(8,14,28,.46);
  border-radius:24px;padding:16px;backdrop-filter:blur(12px)
}
.map-placeholder{
  min-height:280px;display:grid;place-items:center;text-align:center;padding:28px;
  border:1px dashed rgba(255,255,255,.22);border-radius:20px;background:rgba(5,9,18,.18)
}
.map-placeholder span{font-size:3rem}.map-placeholder strong{font-size:1.3rem}
.map-placeholder p,.map-info p{color:#d7deea;line-height:1.5;margin:.4rem 0 0}
.map-info{margin-top:12px;padding:12px 14px;border-radius:16px;background:rgba(5,9,18,.24)}

nav{grid-template-columns:repeat(6,1fr)}
nav small{font-size:.62rem}

@media(max-width:700px){
  .chat-form{grid-template-columns:1fr}
  .chat-form button{padding:13px}
  .countdown b{font-size:1.05rem}
}

/* v19 cleaner home */
.page[data-page="home"] .hero{
  min-height:330px;
  margin-bottom:12px;
}
.home-status-row{
  display:flex;
  flex-wrap:wrap;
  gap:8px;
  margin-top:10px;
}
.home-status-row span{
  display:inline-flex;
  align-items:center;
  padding:8px 11px;
  border:1px solid rgba(255,255,255,.12);
  border-radius:999px;
  background:rgba(8,14,28,.34);
  backdrop-filter:blur(10px);
  color:#e9eff8;
  font-size:.76rem;
}
.page[data-page="home"] .sync-status{
  margin-top:8px;
}

/* v20: home cards removed completely */
.page[data-page="home"] .cards{display:none!important}
.page[data-page="home"] .hero{margin-bottom:8px}
.page[data-page="home"] .home-status-row{margin-top:8px}

/* v21 polish */
.countdown-wrap{
  margin-top:16px;
  padding:10px;
  border:1px solid rgba(255,255,255,.11);
  border-radius:18px;
  background:linear-gradient(180deg,rgba(6,10,19,.18),rgba(6,10,19,.08));
  backdrop-filter:blur(10px)
}
.countdown-label{
  display:block;
  margin:0 0 8px 3px;
  font-size:.68rem;
  letter-spacing:.11em;
  text-transform:uppercase;
  font-weight:900;
  color:#ffe0ad
}
.countdown{margin-top:0}
.countdown>div{
  padding:11px 6px;
  border-radius:13px;
  background:rgba(5,9,18,.20);
  border:1px solid rgba(255,255,255,.10)
}
.countdown b{font-size:1.35rem;letter-spacing:-.03em}
.countdown span{font-size:.62rem;text-transform:uppercase;letter-spacing:.06em}

.chat-list{
  display:flex;
  flex-direction:column;
  gap:10px;
  margin-top:12px
}
.chat-msg{
  position:relative;
  display:grid;
  grid-template-columns:38px 1fr;
  gap:10px;
  padding:12px;
  border-radius:20px;
  background:linear-gradient(180deg,rgba(8,14,28,.50),rgba(8,14,28,.38));
  box-shadow:0 8px 24px rgba(0,0,0,.10)
}
.chat-avatar{
  width:38px;height:38px;border-radius:50%;
  display:grid;place-items:center;
  background:linear-gradient(135deg,rgba(224,125,86,.9),rgba(130,67,155,.9));
  font-weight:900;color:white
}
.chat-body{min-width:0}
.chat-msg header{margin:0 0 5px;padding:0}
.chat-msg strong{font-size:.92rem}
.chat-msg time{font-size:.68rem;opacity:.8}
.chat-msg p{font-size:.92rem}
.chat-form{
  border-radius:22px;
  box-shadow:0 10px 28px rgba(0,0,0,.10)
}

.map-card{
  padding:14px;
  border-radius:26px;
  box-shadow:0 10px 28px rgba(0,0,0,.10)
}
.map-placeholder{
  min-height:255px;
  border-style:solid;
  background:
    radial-gradient(circle at 30% 25%,rgba(244,194,122,.13),transparent 28%),
    linear-gradient(180deg,rgba(5,9,18,.20),rgba(5,9,18,.08))
}
.map-pin{
  width:64px;height:64px;border-radius:20px;
  display:grid;place-items:center;
  font-size:2.2rem;
  background:rgba(8,14,28,.42);
  border:1px solid rgba(255,255,255,.12)
}
.map-badge{
  display:inline-flex;
  margin-top:10px;
  padding:7px 10px;
  border-radius:999px;
  font-size:.7rem;
  color:#ffe0ad;
  border:1px solid rgba(244,194,122,.24);
  background:rgba(115,53,35,.28)
}
.map-quick-grid{
  display:grid;
  grid-template-columns:1fr 1fr;
  gap:10px;
  margin-top:10px
}
.map-quick{
  display:flex;gap:10px;align-items:center;
  padding:12px;
  border-radius:17px;
  background:rgba(5,9,18,.22);
  border:1px solid rgba(255,255,255,.10)
}
.map-quick>span{font-size:1.25rem}
.map-quick strong{display:block;font-size:.88rem}
.map-quick small{display:block;color:#c9d3df;margin-top:2px;font-size:.72rem}

@media(max-width:700px){
  .map-quick-grid{grid-template-columns:1fr}
  .countdown b{font-size:1.08rem}
}
